// batchSpec returns the entities that the update assigns and the spec of the update.
func (_u *FileTypeUpdateBulk) batchSpec() ([]*FileType, *sqlgraph.BatchUpdateSpec, error) {
	nodes := make([]*FileType, len(_u.builders))
	_spec := &sqlgraph.BatchUpdateSpec{
		Nodes:         make([]*sqlgraph.UpdateSpec, len(_u.builders)),
		PostgresTypes: postgresColumnTypes[filetype.Table],
	}
	for index, builder := range _u.builders {
		if builder.err != nil {
			return nil, nil, builder.err
		}
		if err := builder.defaults(); err != nil {
			return nil, nil, err
		}
		if err := builder.check(); err != nil {
			return nil, nil, err
		}
		node, err := builder.updateSpec()
		if err != nil {
			return nil, nil, err
		}
		nodes[index] = &FileType{config: _u.config}
		node.Assign = nodes[index].assignValues
		node.ScanValues = nodes[index].scanValues
		_spec.Nodes[index] = node
	}
	if ps := _u.predicates; len(ps) > 0 {
		_spec.Predicate = func(selector *sql.Selector) {
			for i := range ps {
				ps[i](selector)
			}
		}
	}
	return nodes, _spec, nil
}

func (_u *FileTypeUpdateBulk) sqlSave(ctx context.Context, _spec *sqlgraph.BatchUpdateSpec) error {
	if err := sqlgraph.BatchUpdate(ctx, _u.driver, _spec); err != nil {
		if _, ok := err.(*sqlgraph.NotFoundError); ok {
			err = &NotFoundError{filetype.Label}
		} else if sqlgraph.IsConstraintError(err) {
			err = &ConstraintError{msg: err.Error(), wrap: err}
		}
		return err
	}
	return nil
}
